    // persisted in localStorage, rotates on login\n  userId?:    string;          // nullable until authenticated\n  deviceId:   string;          // fingerprint (hashed user-agent + screen)\n  timestamp:  string;          // ISO 8601 UTC\n  url:        string;\n  referrer?:  string;\n  properties: Record<string, unknown>;\n}\n\nexport type AnalyticsEventType =\n  | 'page_view'\n  | 'product_impression'\n  | 'product_click'\n  | 'add_to_cart'\n  | 'remove_from_cart'\n  | 'checkout_started'\n  | 'checkout_step_completed'\n  | 'purchase_completed'\n  | 'search_performed'\n  | 'promo_applied';\n"})}),"\n",(0,r.jsx)(n.h3,{id:"event-examples",children:"Event examples"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-typescript",children:"// Page view\n{\n  eventType: 'page_view',\n  properties: { page: '/products/iphone-16', category: 'electronics' }\n}\n\n// Add to cart\n{\n  eventType: 'add_to_cart',\n  properties: { sku: 'IPHONE16-128-BLK', price: 999.99, qty: 1, source: 'pdp' }\n}\n\n// Checkout step\n{\n  eventType: 'checkout_step_completed',\n  properties: { step: 2, stepName: 'shipping_address', cartTotal: 1049.98 }\n}\n\n// Purchase completed (mirrors payment.captured domain event)\n{\n  eventType: 'purchase_completed',\n  properties: { orderId: 'ORD-123', revenue: 1049.98, items: 3, coupon: 'SUMMER10' }\n}\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"ingest-service-nestjs",children:"Ingest Service (NestJS)"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-typescript",children:"// src/ingest/ingest.controller.ts\nimport {\n  Controller, Post, Body, Ip, Headers, HttpCode, BadRequestException\n} from '@nestjs/common';\nimport { KafkaProducerService } from '../kafka/kafka-producer.service';\nimport { InjectRedis } from '@liaoliaots/nestjs-redis';\nimport Redis from 'ioredis';\nimport { AnalyticsEvent } from '../schemas/analytics-event.schema';\n\n@Controller('v1/track')\nexport class IngestController {\n  constructor(\n    private readonly kafka: KafkaProducerService,\n    @InjectRedis() private readonly redis: Redis,\n  ) {}\n\n  @Post()\n  @HttpCode(202)\n  async track(\n    @Body() events: AnalyticsEvent[],\n    @Ip() ip: string,\n    @Headers('x-session-id') sessionId: string,\n  ): Promise<{ accepted: number }> {\n    if (!Array.isArray(events) || events.length > 100) {\n      throw new BadRequestException('Expected array of 1\u2013100 events');\n    }\n\n    // Dedup: skip events already seen (client retry on network failure)\n    const pipeline = this.redis.pipeline();\n    for (const e of events) {\n      pipeline.set(`analytics:dedup:${e.eventId}`, '1', 'EX', 86400, 'NX');\n    }\n    const results = await pipeline.exec();\n\n    const newEvents = events.filter((_, i) => results?.[i]?.[1] === 1);\n\n    if (newEvents.length > 0) {\n      await this.kafka.sendBatch(\n        'analytics-events',\n        newEvents.map(e => ({\n          key:   e.sessionId,         // partition by session for ordered replay\n          value: JSON.stringify({ ...e, ip }),\n        }))\n      );\n    }\n\n    return { accepted: newEvents.length };\n  }\n}\n"})}),"\n",(0,r.jsx)(n.h3,{id:"kafka-producer-batched",children:"Kafka Producer (batched)"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-typescript",children:"// src/kafka/kafka-producer.service.ts\nimport { Injectable, OnModuleInit } from '@nestjs/common';\nimport { Kafka, Producer, CompressionTypes } from 'kafkajs';\n\n@Injectable()\nexport class KafkaProducerService implements OnModuleInit {\n  private producer: Producer;\n\n  constructor() {\n    const kafka = new Kafka({ brokers: process.env.KAFKA_BROKERS!.split(',') });\n    this.producer = kafka.producer({\n      idempotent: true,          // exactly-once produce semantics\n      transactionTimeout: 30_000,\n    });\n  }\n\n  async onModuleInit() { await this.producer.connect(); }\n\n  async sendBatch(\n    topic: string,\n    messages: Array<{ key: string; value: string }>,\n  ): Promise<void> {\n    await this.producer.send({\n      topic,\n      compression: CompressionTypes.GZIP,\n      messages,\n    });\n  }\n}\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"stream-processing-dataflow--flink",children:"Stream Processing (Dataflow / Flink)"}),"\n",(0,r.jsxs)(n.p,{children:["The Flink job consumes ",(0,r.jsx)(n.code,{children:"analytics-events"})," plus domain events from ",(0,r.jsx)(n.code,{children:"order-events"})," and ",(0,r.jsx)(n.code,{children:"payment-events"}),", applying windowed aggregations before writing to Elasticsearch and BigQuery."]}),"\n",(0,r.jsx)(n.h3,{id:"windowed-aggregations",children:"Windowed aggregations"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:"# analytics-pipeline/src/pipeline.py (Apache Beam / Dataflow)\nimport apache_beam as beam\nfrom apache_beam.transforms.window import FixedWindows, SlidingWindows\nfrom apache_beam.options.pipeline_options import PipelineOptions\n\ndef run():\n    options = PipelineOptions(\n        runner='DataflowRunner',\n        project='ecom-prod',\n        region='us-central1',\n        streaming=True,\n        job_name='analytics-streaming',\n    )\n\n    with beam.Pipeline(options=options) as p:\n        events = (\n            p\n            | 'ReadKafka' >> beam.io.ReadFromKafka(\n                consumer_config={'bootstrap.servers': '${KAFKA_BROKERS}'},\n                topics=['analytics-events', 'order-events', 'payment-events'],\n            )\n            | 'ParseJSON' >> beam.Map(lambda m: json.loads(m[1]))\n        )\n\n        # 1-minute fixed windows \u2192 Elasticsearch (real-time dashboards)\n        (\n            events\n            | 'Window1m' >> beam.WindowInto(FixedWindows(60))\n            | 'CountByType' >> beam.combiners.Count.PerKey(\n                beam.Map(lambda e: e['eventType'])\n              )\n            | 'WriteES' >> beam.io.WriteToElasticsearch(\n                host='${ES_HOST}',\n                index='analytics-realtime',\n            )\n        )\n\n        # 60-second micro-batch \u2192 BigQuery (append-only partitioned table)\n        (\n            events\n            | 'Window60s' >> beam.WindowInto(FixedWindows(60))\n            | 'WriteBQ' >> beam.io.WriteToBigQuery(\n                table='ecom-prod:analytics.events',\n                schema='AUTO_DETECT',\n                write_disposition=beam.io.BigQueryDisposition.WRITE_APPEND,\n                create_disposition=beam.io.BigQueryDisposition.CREATE_IF_NEEDED,\n            )\n        )\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"bigquery-schema--partitioning",children:"BigQuery Schema & Partitioning"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-sql",children:"-- analytics.events (partitioned by event_date, clustered by event_type)\nCREATE TABLE `ecom-prod.analytics.events`\n(\n  event_id      STRING NOT NULL,\n  event_type    STRING NOT NULL,\n  session_id    STRING,\n  user_id       STRING,\n  device_id     STRING,\n  event_date    DATE NOT NULL,\n  ts            TIMESTAMP NOT NULL,\n  url           STRING,\n  referrer      STRING,\n  properties    JSON\n)\nPARTITION BY event_date\nCLUSTER BY event_type, user_id\nOPTIONS (\n  partition_expiration_days = 730,  -- 2-year retention\n  require_partition_filter = TRUE   -- prevent full-table scans\n);\n\n-- analytics.orders (materialized from payment-events)\nCREATE TABLE `ecom-prod.analytics.orders`\n(\n  order_id      STRING NOT NULL,\n  user_id       STRING NOT NULL,\n  order_date    DATE NOT NULL,\n  revenue       NUMERIC NOT NULL,\n  item_count    INT64,\n  coupon_code   STRING,\n  payment_method STRING,\n  status        STRING\n)\nPARTITION BY order_date\nCLUSTER BY user_id, status;\n"})}),"\n",(0,r.jsx)(n.h3,{id:"key-analytics-queries",children:"Key analytics queries"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-sql",children:"-- Daily GMV (last 30 days)\nSELECT\n  order_date,\n  SUM(revenue)    AS gmv,\n  COUNT(*)        AS order_count,\n  SUM(revenue) / COUNT(*) AS aov\nFROM `ecom-prod.analytics.orders`\nWHERE order_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY)\n  AND status = 'COMPLETED'\nGROUP BY order_date\nORDER BY order_date DESC;\n\n-- Checkout funnel (last 7 days)\nSELECT\n  step,\n  COUNT(DISTINCT session_id) AS sessions,\n  SAFE_DIVIDE(\n    COUNT(DISTINCT session_id),\n    FIRST_VALUE(COUNT(DISTINCT session_id)) OVER (ORDER BY step_order)\n  ) AS conversion_rate\nFROM (\n  SELECT\n    session_id,\n    CASE event_type\n      WHEN 'product_click'           THEN 'step_1_product_view'\n      WHEN 'add_to_cart'             THEN 'step_2_add_to_cart'\n      WHEN 'checkout_started'        THEN 'step_3_checkout'\n      WHEN 'checkout_step_completed' THEN 'step_4_payment'\n      WHEN 'purchase_completed'      THEN 'step_5_purchase'\n    END AS step,\n    CASE event_type\n      WHEN 'product_click'           THEN 1\n      WHEN 'add_to_cart'             THEN 2\n      WHEN 'checkout_started'        THEN 3\n      WHEN 'checkout_step_completed' THEN 4\n      WHEN 'purchase_completed'      THEN 5\n    END AS step_order\n  FROM `ecom-prod.analytics.events`\n  WHERE event_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY)\n    AND event_type IN (\n      'product_click','add_to_cart','checkout_started',\n      'checkout_step_completed','purchase_completed'\n    )\n)\nWHERE step IS NOT NULL\nGROUP BY step, step_order\nORDER BY step_order;\n\n-- Top products by revenue (last 7 days)\nSELECT\n  JSON_VALUE(properties, '$.sku')   AS sku,\n  SUM(JSON_VALUE(properties, '$.price')::FLOAT64 * JSON_VALUE(properties, '$.qty')::INT64) AS revenue,\n  COUNT(*)                          AS add_to_cart_events\nFROM `ecom-prod.analytics.events`\nWHERE event_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY)\n  AND event_type = 'add_to_cart'\nGROUP BY sku\nORDER BY revenue DESC\nLIMIT 20;\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"elasticsearch--real-time-dashboards",children:"Elasticsearch \u2014 Real-Time Dashboards"}),"\n",(0,r.jsx)(n.p,{children:"Elasticsearch stores the last 7 days of raw and aggregated events for live dashboard queries (sub-second response)."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-typescript",children:"// src/analytics/analytics-query.service.ts\nimport { Injectable } from '@nestjs/common';\nimport { ElasticsearchService } from '@nestjs/elasticsearch';\n\n@Injectable()\nexport class AnalyticsQueryService {\n  constructor(private readonly es: ElasticsearchService) {}\n\n  /** Active users in last 5 minutes (flash sale monitor) */\n  async getActiveUsers(): Promise<number> {\n    const result = await this.es.search({\n      index: 'analytics-realtime',\n      body: {\n        query: {\n          range: { ts: { gte: 'now-5m' } },\n        },\n        aggs: {\n          active_users: { cardinality: { field: 'session_id' } },\n        },\n        size: 0,\n      },\n    });\n    return (result.aggregations?.active_users as any)?.value ?? 0;\n  }\n\n  /** Revenue in the last hour (rolling) */\n  async getLiveRevenue(): Promise<number> {\n    const result = await this.es.search({\n      index: 'analytics-realtime',\n      body: {\n        query: {\n          bool: {\n            filter: [\n              { term:  { eventType: 'purchase_completed' } },\n              { range: { ts: { gte: 'now-1h' } } },\n            ],\n          },\n        },\n        aggs: {\n          total_revenue: {\n            sum: { field: 'properties.revenue' },\n          },\n        },\n        size: 0,\n      },\n    });\n    return (result.aggregations?.total_revenue as any)?.value ?? 0;\n  }\n\n  /** Real-time funnel drop-off (last 30 min) */\n  async getFunnelStats(): Promise<FunnelStep[]> {\n    const result = await this.es.search({\n      index: 'analytics-realtime',\n      body: {\n        query: { range: { ts: { gte: 'now-30m' } } },\n        ag